import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); int[] a = new int[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); } int k = Integer.parseInt(br.readLine().trim()); boolean[] disliked = new boolean[n + 1]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < k; i++) { disliked[Integer.parseInt(st.nextToken())] = true; } StringBuilder sb = new StringBuilder(); boolean first = true; for (int i = 0; i < n; i++) { if (!disliked[a[i]]) { if (!first) { sb.append(" "); } sb.append(a[i]); first = false; } } out.println(sb.toString()); } out.flush(); out.close(); } }